INSERT INTO notification_templates (notification_type, recipient_type, channel, subject_template, body_template, active, created_at, updated_at) VALUES
('APPOINTMENT_CONFIRMATION', 'PATIENT', 'EMAIL', 'Xác nhận lịch hẹn với [[${doctorName}]]', '<html><body style="font-family:Arial,sans-serif"><h2>Lịch hẹn đã được xác nhận</h2><p>Xin chào [[${recipientName}]],</p><p>Lịch hẹn với bác sĩ <strong>[[${doctorName}]]</strong> đã được xác nhận.</p><p><strong>Ngày:</strong> [[${appointmentDate}]]</p><p><strong>Giờ:</strong> [[${appointmentTime}]]</p><p><strong>Phòng khám:</strong> [[${clinicName}]]</p><p><strong>Phòng:</strong> [[${roomName}]]</p><p><strong>Lý do khám:</strong> [[${reason}]]</p><p>Trân trọng,<br/>FClinic</p></body></html>', TRUE, NOW(), NOW()),
('APPOINTMENT_CANCELLATION', 'PATIENT', 'EMAIL', 'Lịch hẹn với [[${doctorName}]] đã bị hủy', '<html><body style="font-family:Arial,sans-serif"><h2>Lịch hẹn đã bị hủy</h2><p>Xin chào [[${recipientName}]],</p><p>Lịch hẹn với bác sĩ <strong>[[${doctorName}]]</strong> đã bị hủy.</p><p><strong>Ngày:</strong> [[${appointmentDate}]]</p><p><strong>Giờ:</strong> [[${appointmentTime}]]</p><p><strong>Phòng khám:</strong> [[${clinicName}]]</p><p><strong>Lý do hủy:</strong> [[${cancellationReason}]]</p><p>Trân trọng,<br/>FClinic</p></body></html>', TRUE, NOW(), NOW()),
('APPOINTMENT_RESCHEDULED', 'PATIENT', 'EMAIL', 'Lịch hẹn với [[${doctorName}]] đã được đổi lịch', '<html><body style="font-family:Arial,sans-serif"><h2>Lịch hẹn đã được đổi lịch</h2><p>Xin chào [[${recipientName}]],</p><p>Lịch hẹn với bác sĩ <strong>[[${doctorName}]]</strong> đã được đổi sang thời gian mới.</p><p><strong>Ngày cũ:</strong> [[${previousAppointmentDate}]]</p><p><strong>Giờ cũ:</strong> [[${previousAppointmentTime}]]</p><p><strong>Ngày mới:</strong> [[${appointmentDate}]]</p><p><strong>Giờ mới:</strong> [[${appointmentTime}]]</p><p><strong>Phòng khám:</strong> [[${clinicName}]]</p><p><strong>Phòng:</strong> [[${roomName}]]</p><p>Trân trọng,<br/>FClinic</p></body></html>', TRUE, NOW(), NOW()),
